const grid=document.querySelector('#projects');
if(grid){
function render(filter='all'){
grid.innerHTML=projects.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="project-card"><div class="project-visual" style="background:${p.color}">${p.image?`<button class="preview-image" data-preview="${p.name}" aria-label="View ${p.name} screenshots"><img src="assets/${p.image}" alt="${p.name}: ${p.evidence}" loading="lazy"><span class="preview-hint">View screenshots ↗</span></button>`:`<div class="chat-preview"><div class="chat-header"><span class="chat-avatar">G</span><div><strong>GabbiDoc</strong><small>Kiki · AI health assistant</small></div></div><div class="chat-body"><div class="chat-bubble">Hi! I’m Kiki, your AI health assistant from GabbiDoc.<small>Illustrative welcome message</small></div><div class="chat-bubble sent">What can I do here?</div><div class="chat-bubble">Describe symptoms<br>Upload a lab result<br>View your health profile<br>Manage subscription plans</div></div></div>`}<span class="mock-label">${p.imageLabel||(p.image?'LOCAL APP SCREENSHOT':'ILLUSTRATIVE CONVERSATION · NO PATIENT DATA')}</span></div><div class="project-meta"><div><h3>${p.name}</h3><p>${p.type}</p></div><button data-project="${p.name}" aria-label="Read ${p.name} case study">↗</button></div><p class="project-summary">${p.summary}</p><div class="case-snapshot"><div><span>THE CHALLENGE</span><p>${p.challenge}</p></div><div><span>THE APPROACH</span><p>${p.approach}</p></div></div><div class="project-card-footer"><span>${p.stack}</span><button data-details="${p.name}">View case study & previews ↗</button>${p.links.length?`<a href="${p.links[0][1]}" target="_blank" rel="noopener noreferrer">Visit project ↗</a>`:''}</div></article>`).join('');
}
render();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));
const dialog=document.querySelector('dialog');grid.addEventListener('click',event=>{const button=event.target.closest('[data-project], [data-preview], [data-details]');if(!button)return;const p=projects.find(p=>p.name===(button.dataset.project||button.dataset.preview||button.dataset.details));document.querySelector('#project-detail').innerHTML=`<div class="eyebrow">PROJECT NOTES / ${p.type.toUpperCase()}</div><h2>${p.name}</h2><p>${p.summary}</p><div class="detail-tags">${p.stack}</div>${p.gallery?`<div class="project-gallery">${p.gallery.map(item=>`<figure><a href="assets/${item.src}" target="_blank" rel="noopener noreferrer" aria-label="Open full screenshot: ${item.caption}"><img src="assets/${item.src}" alt="${item.caption}"></a><figcaption>${item.caption} · Open full size ↗</figcaption></figure>`).join('')}</div>`:''}<h3>The problem</h3><p>${p.problem}</p><h3>The build</h3><p>${p.build}</p><h3>The challenge</h3><p>${p.challenge}</p><h3>The approach</h3><p>${p.approach}</p><h3>What was built</h3><p>${p.result}</p><h3>The engineering lesson</h3><p>${p.lesson}</p><div class="project-destinations">${p.links.map(([label,url])=>`<a class="text-link" href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div><small>${p.evidence}</small>`;dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
}
const inquiryForm=document.querySelector('#brief-form');
function prepareProjectEmail(){
const data=new FormData(inquiryForm);const get=key=>String(data.get(key)||'').trim();
const subject='Project inquiry: '+get('title').replace(/[\r\n]/g,' ');
const body=['Hi Olajide,','I’d like to discuss a project with you.','CONTACT','Name: '+get('name'),'Email: '+get('email'),'Company: '+(get('company')||'Not specified'),'PROJECT: '+get('title'),'THE IDEA',get('idea'),'GOALS & FEATURES',get('features')||'Let’s discuss','PREFERRED APPROACH',get('approach')||'I’d like your guidance','TIMELINE',get('timeline')||'Let’s discuss','BUDGET',get('budget')||'Let’s discuss','LINKS & ADDITIONAL DETAILS',get('links')||'None yet'].join('\n\n');
return {subject,body,mailto:'mailto:daotechnology18@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)};
}
function showEmailFallback(draft){document.querySelector('#email-fallback').hidden=false;document.querySelector('#email-draft').value=draft.subject+'\n\n'+draft.body;document.querySelector('#gmail-compose').href='https://mail.google.com/mail/?view=cm&fs=1&to=daotechnology18%40gmail.com&su='+encodeURIComponent(draft.subject)+'&body='+encodeURIComponent(draft.body);}
inquiryForm?.addEventListener('submit',event=>{event.preventDefault();if(!inquiryForm.reportValidity())return;const draft=prepareProjectEmail();showEmailFallback(draft);const link=document.createElement('a');link.href=draft.mailto;link.hidden=true;document.body.append(link);link.click();link.remove();document.querySelector('#brief-status').textContent='Your email draft is ready. Complete sending in your email app. If it didn’t open, use the options below.';});
document.querySelector('#copy-brief')?.addEventListener('click',async()=>{if(!inquiryForm.reportValidity())return;const draft=prepareProjectEmail();showEmailFallback(draft);try{await navigator.clipboard.writeText(draft.subject+'\n\n'+draft.body);document.querySelector('#brief-status').textContent='Project details copied. Paste them into an email to daotechnology18@gmail.com.';}catch{const area=document.querySelector('#email-draft');area.focus();area.select();document.querySelector('#brief-status').textContent='Your project details are selected below. Copy and paste them into your email.';}});
